uint32_t ucd_cc_compose(uint32_t lhs, uint32_t rhs) {
  if (lhs >= 0x110000u) return 0u;
  uint32_t off = ucd_cc_stage2[(size_t)ucd_cc_stage1[lhs >> 7] * 128u + (lhs & 127u)];
  if (off == 0u) return 0u;
  uint32_t count = ucd_cc_payload[off];
  for (uint32_t k = 0; k < count; k++) {
    if (ucd_cc_payload[off + 1u + (2u * k)] == rhs)
      return ucd_cc_payload[off + 2u + (2u * k)];
  }
  return 0u;
}
